        if (payGo === 'priority') {
          payGoHeaders['X-Vertex-AI-LLM-Shared-Request-Type'] = 'priority';
        } else if (payGo === 'priority-only') {
          payGoHeaders['X-Vertex-AI-LLM-Request-Type'] = 'shared';
          payGoHeaders['X-Vertex-AI-LLM-Shared-Request-Type'] = 'priority';
